documents.issue_rows:
yamaa: "1.0"
type: spec
domain: ADSL
keys: [USUBJID]
input: {DM: input/dm.csv}
output: {path: out.csv, columns: [USUBJID, N, ZZZ]}
columns:
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: N, type: float, derivation: DM.AGE}

documents.formula:
yamaa: "1.0"
type: spec
domain: ADSL
keys: [USUBJID]
input: {DM: {path: input/dm.csv, types: {AGE: float, WT: float}}}
output: {path: out.csv, columns: [USUBJID, A, B]}
columns:
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: A, type: float, derivation: 'B + DM.AGE + DM.WT'}
  - {name: B, type: float, derivation: DM.AGE}

documents.driver:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID]
input: {SRC: input/src.csv}
output: {path: out.csv, columns: [ID]}
intermediates:
  - {id: DRV, dataset: SRC, filter: "SRC.ID <> 'z'", require_match: false}
columns:
  - {name: ID, type: str}
rows:
  - {id: all, dataset: DRV, derivations: {ID: DRV.ID}}

documents.lookup:
yamaa: "1.0"
type: spec
domain: OUT
keys: [X]
input: {SRC: input/src.csv, RIGHT: {path: input/right.csv, key: [X]}}
base: SRC
output: {path: out.csv, columns: [X, W]}
intermediates:
  - {id: LOOK, dataset: RIGHT, key: [X], derivations: {}}
columns:
  - {name: X, type: str, derivation: SRC.X}
  - {name: W, type: str, derivation: LOOK.K}

documents.odm:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID]
input: {ODM: input/odm.csv}
output: {path: out.csv, columns: [STUDYID, USUBJID, AGE]}
columns:
  - {name: STUDYID, type: str, derivation: ODM.StudyOID}
  - {name: USUBJID, type: str, derivation: ODM.SubjectKey}
  - {name: AGE, type: int, derivation: {value: {odm: NOPE.IT.DM.AGE}, unconvertible: null}}

documents.rows:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID]
input: {SRC: input/src.csv}
base: SRC
output: {path: out.csv, columns: [ID, A]}
intermediates:
  - {id: PREV, dataset: SELF, key: [ID]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: X, type: str, derivation: SRC.X}
  - {name: A, type: str, derivation: PREV.ID}
rows: []

documents.precision:
yamaa: "1.0"
type: spec
domain: ADSL
keys: [USUBJID]
input: {DM: input.csv}
output: {path: out.csv, columns: [USUBJID, N]}
columns:
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: N, type: float, derivation: DM.VALUE}

edits.to:
- {name: A, type: float, derivation: 'C - B'}
- {name: B, type: float, derivation: DM.AGE}
- {name: C, type: float, derivation: DM.WT}
